export default [{"id":303,"question":"إذا دخل أحدٌ المسجد في وقت النَّهي هل يُصلي ركعتين أو يجلس؟","title":"حكم الصلاة في أوقات النهي؟","answer":"الجواب: إذا دخل الإنسانُ وقت النَّهي –مثل: بعد العصر دخل المسجد، ومثل: بعد  الصبح- فإنَّ السنة أن يُصلي ركعتين ولو كان في وقت النَّهي، هذا هو المختار من أقوال أهل العلم، وهذا الذي يقوم عليه الدليلُ، وتُسمَّى هذه الصلاة من ذوات الأسباب، والرسول  قال: إذا دخل أحدُكم المسجدَ فلا يجلس حتى يُصلي ركعتين، ولم يقل: إلا وقت العصر، وإلا وقت الفجر، لا، وقال عليه الصلاة والسلام: مَن جاء والإمام يخطب يوم الجمعة فليركع ركعتين، وليتجوَّز فيهما، فأمره بالركعتين والإمام يخطب، فهذا وقتٌ يُنهى فيه عن القيام للصلاة لو كان جالسًا، ومع هذا أمر أن يُصلي ركعتين ثم يجلس والإمام يخطب؛ وما ذاك إلا لعظم شأن هاتين الركعتين.\nوهكذا صلاة الطواف: لو جاء إلى المسجد الحرام بعد العصر وطاف يُصلي ركعتين مثل تحية المسجد؛ لأنَّها من ذوات الأسباب، وهكذا مثل الصبح؛ لقول النبي ﷺ: يا بني عبد مناف، لا تمنعوا أحدًا طاف بهذا البيت وصلَّى أيَّة ساعةٍ شاء من ليلٍ أو نهارٍ.\nوهكذا في الكسوف: لو كسفت الشمسُ بعد العصر صلَّى الناسُ؛ لأنَّ الرسول ﷺ أمر بذلك، ولم يستثنِ وقتًا دون وقتٍ، فقال: إنَّ الشمس والقمر آيتان من آيات الله، لا ينخسفان لموت أحدٍ من الناس ولا لحياته، فإذا رأيتُم ذلك فصلُّوا وادعوا، وفي اللفظ الآخر: فإذا رأيتُم ذلك فافزعوا إلى الصلاة، وإلى ذكر الله، وإلى دعائه واستغفاره، فهذه الصلاة ليس لها وقتُ نهيٍ، بل متى وُجِد الكسوفُ شُرع للناس الصلاة، ولو كان بعد العصر، ولو طلعت الشمسُ كاسفةً صلّوا صلاة الكسوف، نعم.","link":"https://binbaz.org.sa/fatwas/4305/حكم-الصلاة-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0352.mp3","categories":["أوقات النهي","صلاة الجمعة"]},{"id":845,"question":"ما حكم الصلاة الفرض أو السنة في الأوقات المنهي عنها؟ وما صحة حديث عمر، قال: \"صليتُ العصر ولما تغرب الشمس\"، قال له الرسولُ ﷺ: والله الذي لا إله إلا هو، إنَّك لم تُصلِّ، قم فصلِّ، ثم توضأ بعد المغرب وصلَّى العصر؟","title":"حكم صلاة الفرض والسنة في وقت النهي","answer":"الجواب: الصلاة فيها تفصيل في أوقات النهي:\nأما النوافل المطلقة فلا يجوز فعلها وقت النهي: بعد العصر إلى غروب الشمس، وبعد الصبح إلى ارتفاع الشمس، وعند قيام الشمس، جاء في الأحاديث المتواترة عن رسول الله ﷺ النَّهي عن ذلك.\nأما الصلاة ذات الأسباب: كصلاة الطواف في مكة، وصلاة تحية المسجد، والكسوف، ففيها خلافٌ بين أهل العلم، والصواب أنها تجوز، تجوز ذوات الأسباب في أوقات النَّهي؛ للأحاديث الصَّحيحة الواردة في ذلك المطلقة، ولقوله ﷺ: يا بني عبد مناف، لا تمنعوا أحدًا طاف بهذا البيت وصلَّى أية ساعةٍ شاء، من ليلٍ أو نهارٍ، وقوله ﷺ في الكسوف: فإذا وجدتم ذلك فصلُّوا وادعوا يعني: الكسوف، فإنَّهما آيتان من آيات الله، لا ينكسفان لموت أحدٍ ولا لحياته، فإذا رأيتم ذلك فافزعوا إلى الصلاة، فصلوا وادعوا، ولم يخصّ ذلك في وقتٍ دون وقتٍ، فدلَّ على أن صلاة الكسوف يجوز فعلها في وقت النَّهي: كالعصر، وحديث: إذا دخل أحدُكم المسجد فلا يجلس حتى يُصلي ركعتين عامٌّ أيضًا، على الصحيح.\nأما الحديث الذي أشرتَ إليه فليس كما ذكرتَ: في يوم الأحزاب قال عمر: ما صليتُ العصر حتى كادت الشمسُ تغرب، فقال النبيُّ: ما صليتُها، هو نفسه، ما قال: ما صليتَها أنت، قال النبي: ما صليتُها أنا، يعني: النبي ﷺ، ثم توضؤوا وصلّوا العصر بعدما غربت الشمس، ثم صلوا بعدها المغرب، هذا يوم الأحزاب صلاة الفريضة.\nوهذا احتجَّ به العلماء، وجمع بعض العلماء على أن المجاهدين إذا اشتدَّ القتال وحمي الوطيس ولم يتيسر لهم الصلاة جاز تأخيرها عن وقتها حتى تُصلَّى على وجهٍ صحيحٍ، فالنبي ﷺ وأصحابه في بعض أيام العدو مع الأحزاب لم يتيسر لهم أن يُصلّوا العصر حتى غابت الشمس، حتى كادت الشمس أن تغرب، وأخَّروها من أجل شغلهم بالقتال مع أعداء الله، فهذا يدل على الصحيح إذا دعت إليه الضَّرورة، ولو فات الوقت.\nقال بعضُ أهل العلم: إنَّ هذا كان قبل شرعية صلاة الخوف، والصواب أنه ليس قبلها، بل بعدها، ولو فرضنا أنه قبلها فالجمع مُقدَّم على النسخ، فصلاة الخوف تُصلَّى حيث أمكن، وإذا لم يمكن فعلها جاز التأخير للحاجة الشَّديدة أو الضَّرورة، كما فعل النبيُّ ﷺ يوم الأحزاب.\nوثبت من حديث أنسٍ رضي الله تعالى عنه: أن الصحابة في قتال الفرس لما فتحوا تُسْتَر فتحوها عند طلوع الفجر، والناس بعضهم على الأبواب، وبعضهم على السور، وبعضهم نزل البلد، فلم يتمكنوا من صلاة الفجر إلا ضُحًى، قال أنسٌ : \"فما أُحب أنَّ لي بها كذا وكذا\"؛ لأنَّهم أخَّروها لعذرٍ شرعيٍّ وضرورةٍ، وهو أنهم على أبواب البلد، وعلى سورها، والقتال حامٍ بينهم وبين العدو، ليس في إمكانهم أن يُصلوا ذاك الوقت.\nفالحاصل أنه يجوز على الصحيح تأخير الصلاة عن وقتها في وقت الحرب والجهاد مع الأعداء إذا لم تُمكن صلاة الخوف.","link":"https://binbaz.org.sa/fatwas/20884/حكم-صلاة-الفرض-والسنة-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0679ما حكم صلاة الفرض والسنة في الأوقات المنهي عنه؟ ابن باز فتاوى المحاضرات.mp3","categories":["أوقات النهي","صلاة الجمعة"]},{"id":2467,"question":"(تحية المسجد) وقت النهي يصليها؟","title":"هل تُصلّى تحية المسجد في أوقات النهي؟","answer":"الجواب:\nولو في وقت النهي، على الصواب، الصواب ما لها وقت نهي، صلاة الكسوف كذلك ما لها وقت نهي.","link":"https://binbaz.org.sa/fatwas/22596/هل-تصلى-تحية-المسجد-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تصلى تحية المسجد في أوقات النهي.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":2474,"question":"إذا صلى حتى يدخل الخطيب ما يدخل في وقت النهي؟","title":"حكم النافلة يوم الجمعة حتى دخول الخطيب","answer":"الجواب:\nما في وقت نهي يوم الجمعة، الضحى ما فيه وقت نهي، ولهذا النبي حث على الصلاة حتى يدخل الإمام، لو فيها وقت نهي لاستثنى عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22603/حكم-النافلة-يوم-الجمعة-حتى-دخول-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من صلى حتى يدخل الخطيب ما يدخل في وقت النهي.mp3","categories":["أوقات النهي"]},{"id":3511,"question":"تحية المسجد بعد العصر تسقط؟","title":"هل تسقط تحية المسجد بعد العصر والفجر؟","answer":"الجواب: لا، من ذوات الأسباب، يصلي تحية المسجد، إذا دخل المسجد يصلي تحية المسجد بعد العصر وبعد الفجر.","link":"https://binbaz.org.sa/fatwas/23691/هل-تسقط-تحية-المسجد-بعد-العصر-والفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسقط تحية المسجد بعد العصر.mp3","categories":["أوقات النهي"]},{"id":3521,"question":"الصحيح في وقت النهي بعد الفجر وبعد العصر: يبدأ بدخول الوقت والأذان، أو يبدأ بفعل الصلاة؟","title":"متى يبدأ وقت النهي بعد الفجر والعصر؟","answer":"الجواب: العصر بفعل الصلاة. والفجر بطلوع الفجر، إلا سنة الفجر.","link":"https://binbaz.org.sa/fatwas/23702/متى-يبدا-وقت-النهي-بعد-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ وقت النهي بعد الفجر وبعد العصر.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":3584,"question":"صلاة الاستخارة هل هي من ذوات الأسباب؟","title":"هل صلاة الاستخارة من ذوات الأسباب؟","answer":"الجواب: قد تكون بعض الأحيان، وإلا ما هي من ذوات الأسباب، قد يمكن يؤجلها إلى أوقات غير أوقات النهي؛ لأن وقتها واسع، يصليها في غير وقت النهي.","link":"https://binbaz.org.sa/fatwas/23766/هل-صلاة-الاستخارة-من-ذوات-الاسباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صلاة الاستخارة من ذوات الأسباب.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":4601,"question":"صلاة الوضوء من ذوات الأسباب؟","title":"هل صلاة الوضوء من ذوات الأسباب؟","answer":"الجواب: نعم، هذا هو الأقرب والله أعلم، إذا كان ما قصد ذلك، إنما توضَّأ لحاجةٍ.","link":"https://binbaz.org.sa/fatwas/24890/هل-صلاة-الوضوء-من-ذوات-الاسباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صلاة الوضوء من ذوات الأسباب.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":4660,"question":"يُصلي ركعتي الإحرام في وقت النَّهي؟","title":"حكم صلاة ركعتي الإحرام في وقت النَّهي","answer":"الجواب: إنسان توضَّأ، سنة الوضوء ما لها وقت نهي، وسنة تحية المسجد، وسنة الكسوف، كلها من ذوات الأسباب.","link":"https://binbaz.org.sa/fatwas/24951/حكم-صلاة-ركعتي-الاحرام-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة ركعتي الإحرام في وقت النَّهي.mp3","categories":["أوقات النهي"]},{"id":5282,"question":"ما حكم تحية المسجد في وقت النهي هل هي واجبة أم مستحبة؟","title":"ما حكم تحية المسجد في وقت النهي؟","answer":"الجواب: تحية المسجد سُنة في جميع الأوقات، تحية المسجد ركعتان في كل وقت على الصحيح، ليس لها وقت نهي، حتى ولو كان الإمام يخطب، إذا دخل يوم الجمعة والإمام يخطب لا يجلس حتى يصلي ركعتين.[1]","link":"https://binbaz.org.sa/fatwas/30920/ما-حكم-تحية-المسجد-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 002.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":5999,"question":"شكرًا لسماحة الشيخ، ونفعنا الله بعلمه، وجزاه الله خير الجزاء، ووردت إلينا تسعة وثلاثون سؤالًا إلى الآن، نترك لسماحة الشيخ الإجابة على ما تيسر منها:أول هذه الأسئلة حسب وروده إلينا: بسم الله الرحمن الرحيم: إذا دخل الرجل المسجد قبل الغروب، فهل يتسنن، أم لا؟","title":"حكم التنفل قبل غروب الشمس","answer":"الجواب: إذا دخل الإنسان المسجد قبل غروب الشمس، أو دخل المسجد قبل طلوع الشمس بعد صلاة الفجر، فهذه الأوقات يقال لها: أوقات النهي عن الصلاة، والرسول ﷺ نهى عن الصلاة بعد الصبح حتى تطلع الشمس، ونهى عن الصلاة بعد العصر حتى تغيب الشمس، تواترت، بهذا الأحاديث عن رسول الله -عليه الصلاة والسلام- ووجب على المسلمين الأخذ بها، وأن يكفوا عن الصلاة بعد الصبح إلى ارتفاع الشمس، وبعد العصر إلى مغيب الشمس.  لكن هناك صلوات لها أسباب، ليست صلاة عادية، بل لها أسباب، أما الصلوات التي ليس لها أسباب فهذا محرم فعلها في أوقات النهي، كونه يقول: أصلي بدون سبب بعد العصر، أو بعد الصبح، أو بعد ارتفاع الشمس، فهذا ممنوع، أو عند قيام الشمس عند وقوفها قبيل الزوال هذا ممنوع. لكن هناك صلوات لها أسباب مثل: الطواف، صلاة الطواف الذي طاف بالكعبة بعد العصر، أو بعد الصبح، ومثل صلاة الكسوف، لو كسفت الشمس بعد العصر، ومثل صلاة الجنازة بعد العصر، وبعد الصبح، ومثل تحية المسجد إذا دخل المسجد بعد الصبح، وبعد العصر، وذهب بعض أهل العلم إلى أن هذه الصلاة مثل غيرها تمنع قال: لا تفعل، ولو أنها ذوات أسباب لا تفعل في أوقات النهي؛ أخذًا بالعموم الذي سمعتم. وقال آخرون من أهل العلم: لا حرج في الصلاة ذات الأسباب، لا حرج فيها أن تؤدى في أوقات النهي إذا كان لها سبب مثل: الصلوات التي سمعتم، مثل: صلاة الطواف، طاف إنسان في الكعبة، في مكة، طاف بعد العصر فهل يصلي؟ نعم الصواب: يصلي؛ لأنها ذات أسباب، ما صلاها هكذا من دون سبب، بل طاف، والطواف سبب، فيصلي ركعتين. كذلك صلاة الكسوف، كذلك تحية المسجد إذا دخل المسجد قبل غروب الشمس يصلي ركعتين، ثم يجلس، هذا هو الأفضل، والأقوى، والأصح. لأن الرسول ﷺ أمر بهذه الصلوات، وقال -عليه الصلاة والسلام-: يا بني عبد مناف لا تمنعوا أحدًا طاف بهذا البيت، وصلى أية ساعة شاء من ليل، أو نهار خرجه الإمام أحمد، وأهل السنن بإسناد صحيح .  وقال في الخسوف: فإذا رأيتم ذلك؛ فصلوا، وادعوا خسوف الشمس، والقمر، ولم يقل إلا وقت النهي.  وكذلك قال: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين فهو جاء يصلي المغرب، أو جاء ليجلس في المسجد قبل طلوع الشمس؛ ليقرأ، أو ليستريح، وهو على وضوء يصلي ركعتين؛ لأنها ذات أسباب، أو قدرت جنازة بعد العصر، أو بعد الصبح، يصلي عليها كما هو العمل، يصلي على الجنازة؛ لأن تأخيرها غير مشروع، وتعجيلها مشروع، أو إنسان توضأ ليقرأ بعد العصر، وتوجه إلى المسجد ليقرأ القرآن، أو ليمس المصحف؛ فالوضوء له صلاة، وصلاته من ذوات الأسباب. فهذه الصلوات التي ذكرنا يقال لها: ذوات الأسباب، والصحيح فيها: أنه لا بأس بفعلها، وأنها مستثناة، خارجة من العموم، فلا بأس أن يصلي ركعتين تحية المسجد بعد العصر على الصحيح، ولا بأس أن يصلي بعد الطواف إذا طاف بعد العصر، أو بعد الصبح في مكة، ولا بأس أن يصلي صلاة الخسوف إذا خسفت الشمس بعد العصر، هذا هو الصواب. ولو ترك؛ لا حرج لو جلس في المسجد، ولم يصلها، أو ما صلوا الكسوف، أو طاف بعد العصر، وأخر الصلاة إلى بعد المغرب، لا حرج في ذلك، لا بأس، لكن المبادرة في ذلك، وصلاة تحية المسجد، وصلاة الطواف، وصلاة الكسوف في وقتها هذا هو الأفضل، هذا هو الصواب، وتكون أحاديث النهي عامة، وهذه الصلوات التي جاء فيها الحديث خاصة مستثناة.  ويلحق بذلك صلاة الجماعة إذا فاتت المسلم، إذا صلى جماعة، ثم جاء إلى مكان لم يصلوا، فصلى معهم، فهذه من ذوات الأسباب، لو صليت مع إخوانك في مسجد من المسجد، العصر، ثم ذهبت إلى الدرس في مسجد آخر، أو لحاجة تريدها في مسجد آخر، فدخلت المسجد، وإذا هم يصلون، فتصلي معهم، ولا تقل هذا بعد العصر، لا أصلي معهم، أو الفجر لا صل معهم، النبي ﷺ أمر الذين يدركون وقتًا يؤخرون فيه الأمراء الصلاة، قال: صل الصلاة لوقتها، فإن أدركتها معهم؛ فصل معهم، فإنها لك نافلة، ولا تقل: صليت، فلا أصلي، فهذا يدل على أنه إذا صلى في أي مسجد، ثم جاء إلى مسجد آخر لحاجة، ووجدهم يصلون العصر، أو الفجر؛ فإنه يصلي معهم، ولا يقل: صليت فلا أصلي، فتكون له نافلة، هذه أيضًا نوع خامس من ذوات الأسباب المستثناة من أحاديث النهي. وصلاة الوضوء أيضًا نوع سادس، فالصواب في هذه المسائل: أن ذوات الأسباب يعفى عنها، ولا بأس أن تؤدى في أوقات النهي، وأنها مستثناة من العموم في أرجح قولي العلماء.  السؤال: النفل المطلق هو الممنوع؟ الجواب: النفل المطلق هو الممنوع نعم. السؤال: إذا كان في المسجد، ثم انتقض وضوءه، وعاد؟ الجواب: يصلي تحية المسجد، وصلاة الوضوء أيضًا، فيجتمع له سنتان: سنة الوضوء، وسنة تحية المسجد. السؤال: هو كان جالس في المسجد؟ الجواب: ولو إذا دخل هذا دخولًا جديدًا، وكذلك بعض الناس قد يشتبه عليه خاصة كثير بعد المغرب، إذا كان جالس قبل الغروب في المسجد، ثم أذن المؤذن؛ فالأفضل أن يصلي ركعتين بعد الأذان، كان أصحاب النبي ﷺ يفعلون ذلك في عهده -عليه الصلاة والسلام- جاء هذا في عدة أحاديث صحيحة عن رسول الله، عليه الصلاة والسلام.  فالصحابة كانوا إذا أذن المؤذن للمغرب؛ قاموا، وصلوا ركعتين قبل الإقامة إذا كانوا جالسين في المسجد ينتظرون، ثم أذن المؤذن؛ فالأفضل، والسنة أن الجالسين يقومون بعد الأذان، ويصلون ركعتين، هذه تخفى على كثير من الناس، ويظن أنها غير مشروعة، وقد قيل لعقبة بن عامر الصحابي الجليل، أمير مصر في ذلك، فقال: إنها سنة كنا نفعلها في عهد النبي ﷺ فقال له السائل: ما يمنعنك الآن؟ قال: الشغل. وثبت في صحيح مسلم عن أنس  أن أصحاب النبي كانوا يفعلونها، فإذا أذن المؤذن وهم جالسون؛ قاموا، فأدوا ركعتين قبل صلاة المغرب، وهكذا بقية الصلوات إذا أذن المؤذن للظهر، أو للعصر، أو للعشاء وأنت جالس؛ تقوم تصلي ركعتين في الفجر، سنة في الفجر، في الظهر، الراتبة إذا كنت ما أديتها، وإذا كنت أديت الراتبة؛ صليت ركعتين؛ لأن النبي -عليه الصلاة والسلام- قال: بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة والعصر كذلك. السؤال: والجمعة يا شيخ؟ الجواب: الجمعة لا، إذا أذن الأذان الأخير؛ يجلس يستمع الخطبة، لكن إذا دخل وهو يخطب؛ يصلي ركعتين، وقد أمر بها النبي ﷺ أمر من دخل أن يصلي ركعتين، ولو أن الإمام يخطب، لكن لا يطول فيهما يتجوز.","link":"https://binbaz.org.sa/fatwas/1372/حكم-التنفل-قبل-غروب-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_330.mp3","categories":["أوقات النهي","صلاة التطوع"]},{"id":6047,"question":"إذا دخلت إلى مسجد قبل أذان المغرب، فهل يجوز أن أصلي، حيث سمعت من البعض يقولون: لا يجوز الركوع بعد الأذان؟","title":"حكم أداء تحية المسجد قبل أذان المغرب","answer":"الجواب: إذا دخل الإنسان المسجد بعد صلاة العصر، أو بعد صلاة الصبح، إذا دخل المسجد، ويريد أن يجلس فيه ليقرأ، أو ليستريحش؛ فإنه يصلي ركعتين، هذا هو الأفضل تحية المسجد، وإن جلس كما قال جماعة من العلماء؛ فلا بأس، فلا حرج. لا ينبغي في هذا التشديد، ولا النزاع، من جلس؛ فلا حرج، ومن صلى ركعتين إذا دخل المسجد بعد صلاة العصر، أو بعد صلاة الصبح فهو أفضل؛ لأنها تحية المسجد؛ ولأنها من ذوات الأسباب، وذوات الأسباب الأرجح فيها أنها تجوز وقت النهي، مثل صلاة الطواف في مكة إذا طاف؛ صلى ركعتين، ومثل صلاة الكسوف إذا كسفت الشمس بعد العصر؛ الأفضل يصلى صلاة الكسوف. كذلك إذا دخل المسجد بعد العصر، أو بعد الصبح؛ الأفضل أن يصلي ركعتين، ثم يجلس، هذا هو الأفضل؛ لقول النبي ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين وهذا عام، يعم ما بعد صلاة العصر، ويعم ما بعد صلاة الصبح، وهذا هو الأرجح من قولي العلماء، رحمهم الله.","link":"https://binbaz.org.sa/fatwas/1453/حكم-اداء-تحية-المسجد-قبل-اذان-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_381.mp3","categories":["أوقات النهي","صلاة التطوع"]},{"id":6093,"question":"إذا دخل الرجل المسجد، وأقيمت الصلاة، وهو قد صلى، ولكن الصلاة هي المغرب، فهل يعيد، أم لا؟ حيث قال بعض العلماء: إن المغرب لا تعاد؛ لأنها وتر، إلا إذا شفعها الرابعة، فهل هذا صحيح؟","title":"حكم شفع صلاة المغرب لمن صلاها نافلة","answer":"الجواب: هذا نعم قاله بعض أهل العلم: أن الوتر في المغرب لا تعاد وترًا، ولكن تعاد شفعًا، ولكن الصحيح أنها تعاد كما هي، وأن هذا القول لا وجه له، النبي -عليه الصلاة والسلام- لما حذر من أمراء يؤخرون الصلاة عن أوقاتها، قال لأبي ذر، ولغيره: صل الصلاة لوقتها، فإن أدركتها معهم؛ فصل، فإنها لك نافلة، ولا تقل صليت فلا أصلي.  فإذا صلى الإنسان في مسجده، أو في بيته لعذر، ثم صادف مسجدًا لحاجة .. يصلي، فإنه يصلي معهم، ولا يقول: صليت فلا أصلي، بل يصلي معهم، ولا يقول: صليت فلا أصلي، بل يصلي معهم، ولو كانت المغرب يصلي معهم، ولا يزيد شيئًا، يصلي معهم، ويسلم معهم؛ عملا بأمر النبي -عليه الصلاة والسلام- قال: صل معهم فإنها لك نافلة ولم يقل: إذا كانت المغرب؛ فزد ركعة، قال: صليت معهم، والرسول يعلم أن المغرب إحدى الصلوات الخمس، فلم يقل لمن أدرك الصلاة مع الجماعة: صل المغرب معهم، وزد فيها ركعة، فلما أطلق؛ دل ذلك على أنه يصلي معهم، كما يصلون، ولا يزيد فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1499/حكم-شفع-صلاة-المغرب-لمن-صلاها-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_429.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":6711,"question":"ما حكم دخول المسجد في وقت غروب الشمس، هل يصلي، أم لا؛ لأن بعض الإخوان ينهون عن أصله، ويقولون فيه نهي؟","title":"حكم صلاة تحية المسجد في أوقات النهي","answer":"الجواب:  إذا دخل قبل غروب الشمس في المسجد غير صلاة المغرب، أو دخل المسجد قبل طلوع الشمس؛ لأجل يستريح، أو لأجل يقرأ، أو يحضر الدرس؛ فالأفضل له أن يصلي ركعتين، وإن جلس أخذًا بما جاء من أحاديث النهي عن الصلاة قبل طلوع الشمس، وقبل غروبها؛ فلا بأس عليه، لأن كثيرًا من أهل العلم قالوا: إن أحاديث النهي ينبغي تقديمها على أحاديث الرخصة.  فالصواب: أن هذه الرخصة مقدمة؛ لأنها من ذوات الأسباب، فإن صلى ركعتين قبل غروب الشمس، وقبل طلوعها لو دخل؛ فهذا أفضل على الصحيح، وإن جلس؛ فلا حرج عليه إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2597/حكم-صلاة-تحية-المسجد-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1093.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7215,"question":"هل يجوز لي أن أصلي النوافل بعدما صليت الوتر بعد صلاة العشاء، علمًا بأن أحد الإخوان قال لي: لا يجوز أن تصلي بعدما أوترت، واحتج بحديث: اجعلوا آخر صلاتكم وترًا نرجو الإيضاح؟","title":"صلاة النوافل بعد صلاة العشاء","answer":"الجواب:\n\nالأفضل أن يختم صلاته بالوتر في الليل كما قاله النبي ﷺ: اجعلوا آخر صلاتكم من الليل وترًا لكن لا بأس أن يصلي بعد الوتر، إنما هذا على سبيل الأفضلية. \n\nوالنبي ﷺ ثبت عنه أنه صلى بعد الوتر، كان يصلي ركعتين بعد الوتر عليه الصلاة والسلام، هذا يدل على جواز أن يصلي بعد الوتر، وألا حرج في ذلك؛ ففعله يبين الجواز.\n\nالسؤال: يشفعها يا شيخ؟\n\nالجواب: يصلي ركعتين بعد الوتر، هذه الشفع، الركعتين شفع، والوتر بقى، ولا يحتاج شيء، الوتر بقى لا يغيره، وإذا صلى ركعتين بعد الوتر؛ فلا بأس، أو صلى في أول الليل، أو أوتر في أول الليل، ثم قام في آخر الليل وصلى ما تيسر، ما يحتاج إلى أن يشفع الوتر، بل الوتر الأول كافي، النبي -عليه الصلاة والسلام- قال: لا وتران في ليلة.","link":"https://binbaz.org.sa/fatwas/3280/صلاة-النوافل-بعد-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1605.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7583,"question":"فضيلة الشيخ! هذه الرسالة التي بين يدينا من المرسل فائز سعيد غرمان الشهري، من بني شهر تنومة، قرية آل علبة، يقول في رسالته: نرجو الاستفسار عما يلي:إذا دخل الرجل في المسجد قبل أذان المغرب بشيء قليل، هل يجوز له أن يتسنن ركعتين قبل الأذان أو يجلس حتى يؤذن المؤذن، أم يقف واقف حتى يؤذن المؤذن، فإن البعض من الناس يقول: ما يجوز الركوع قبل أذان المغرب، والبعض من الناس يقول: لا يجوز الجلوس حتى تصلي ركعتين تحية للمسجد، نرجو الإفادة وفقكم الله؟","title":"ما الذي يُستثنى في أوقات النهي عن الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، رأى رجلاً جلس يوم الجمعة ولم يصل فأمره أن يقوم يصلي ركعتين، فهذا يدل على تأكد هاتين الركعتين في حق من دخل المسجد. \nواختلف العلماء فيمن دخل في أوقات النهي؛ مثل بعد العصر، أو عند غروب الشمس، أو بعد صلاة الفجر، هل يصلي هاتين الركعتين أم يجلس؟ على قولين للعلماء، أصحهما وأرجحهما: أنه يصليهما، يصليهما ولو في وقت النهي؛ لأنهما من ذوات الأسباب، ولهذا شرع النبي صلى الله عليه وسلم أداءهما عند دخول المسجد، فإذا دخل المسجد بعد العصر أو بعد الصبح أو عند غروب الشمس فالأفضل أن يصليهما ثم يجلس، هذا هو الأفضل، وإن جلس ولم يصلهما فلا حرج؛ لأنهما سنة نافلة وليست واجبة عند عامة أهل العلم، فهي سنة وليست واجبة، فإن جلس فلا حرج، وإن صلاهما فهو أفضل، عملاً بهذا الحديث الصحيح. \nأما أحاديث النهي عن الصلاة بعد العصر وبعد الصبح فهي عامة يستثنى منها تحية المسجد، ويستثنى منها ذوات الأسباب، مثل صلاة الطواف في مكة إذا طاف بعد العصر لا بأس يصلي بصلاة الطواف، ومثل صلاة الكسوف لو كسفت الشمس بعد العصر، فالسنة أن يصلي المسلمون صلاة الكسوف بعد العصر؛ لأنها من ذوات الأسباب، فهذا هو الراجح، وإن جلس فلا حرج، ولا ينبغي في مثل هذا التنازع والمخالفة، بل ينبغي في هذا التسامح، فمن صلى فقد أحسن، ومن جلس فلا حرج عليه خروجاً من خلاف العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/4636/ما-الذي-يستثنى-في-اوقات-النهي-عن-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01901.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7852,"question":"أيضاً يقول في رسالته: لقد دخلت المسجد بعد صلاة العصر، بل وقرابة غروب الشمس وأخذت في تحية المسجد فثار علي بعض الحضور جزاهم الله عني خيراً حتى أوشكت أن أجلس وأقطع تحية المسجد، فما رأيكم في ذلك، وفقكم الله؟","title":"حكم صلاة تحية المسجد وذوات الأسباب في أوقات النهي","answer":"الجواب: إذا دخل المسلم المسجد بعد صلاة الفجر ليجلس فيه ليقرأ أو ليستريح، أو دخل المسجد بعد صلاة العصر، أو قرب المغرب لينتظر صلاة المغرب فهو مخير على الصحيح من أقوال العلماء إن شاء صلى التحية وهو أفضل، وإن شاء جلس، ولا ينبغي في هذا النزاع ولا أن يثار عليه، بل ينبغي لمن جهل أن يتعلم، وأحاديث تحية المسجد أحاديث صحيحة، وصلاة تحية المسجد من ذوات الأسباب، والنبي عليه الصلاة والسلام قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، ولما رأى رجلاً يوم الجمعة دخل ولم يصلهما أمره أن يقوم فيصليهما، وكان يخطب النبي ﷺ فرآه دخل المسجد يوم الجمعة ولم يصلهما فأمره أن يقوم فيصليهما، فدل ذلك على تأكدهما، وقد اختلف العلماء في ذلك، فمنهم من أجاز ذلك في وقت النهي، ومنهم من كره ذلك، والصواب أنه لا حرج في ذلك، الصواب والأرجح من قولي العلماء أنه لا حرج في تحية المسجد، بل الأفضل أن يأتي بهما ركعتين، هذا هو الأفضل أن يصلي تحية المسجد ولو كان قبيل الغروب ثم يجلس، هذا هو الأفضل، وإن جلس ولم يصلهما فلا حرج في ذلك، ولا ينبغي في هذا النزاع ولا التشديد بل الأمر واسع، الأكثرون قالوا يجلس، وجماعة من العلماء قالوا الأفضل أنه يصليهما للأحاديث الصحيحة في ذلك، وهذا هو الأرجح أنه يصليهما؛ حرصاً على أداء السنة، ولأنه بهذا لا يشابه الكفار إنما صلاهما أخذاً بالسنة، بخلاف الذي جالس يقوم يصلي لا، لا ما يجوز يصلي في وقت النهي، لكن هذا دخل المسجد فهو يصليهما لأنها تحية المسجد، فلا حرج عليه بل هو الأفضل، وهكذا لو طاف بعد العصر في مكة بالكعبة، أو طاف بعد الصبح قبل طلوع الشمس أو عند طلوعها فإنه يصلي ركعتي الطواف؛ لأنها من ذوات الأسباب، هذا هو الأرجح، وهكذا لو كسفت الشمس مع طلوعها، أو كسفت بعد العصر فالأفضل أنها تصلى صلاة الكسوف؛ لأنها من ذوات الأسباب؛ لقول النبي ﷺ: إذا رأيتم ذلك -أي الكسوف- فصلوا وادعوا، ولم يقل إلا في وقت النهي، فدل ذلك على أن ذوات الأسباب مثل صلاة الطواف، مثل صلاة الكسوف، مثل تحية المسجد، هذه تصلى ولو في وقت النهى على الأرجح، ونسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/5251/حكم-صلاة-تحية-المسجد-وذوات-الاسباب-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05405.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7971,"question":"الرسالة الأولى: هي رسالة سعد صالح الفجري ،يقول في رسالته: بعض الناس يؤدي ركعتين قبل المغرب مستنداً: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، والبعض الآخر لا يصلي بل يجلس مستنداً أن هذا وقت نهي لا تجوز الصلاة فيه، نرجو أن توضحوا لنا هذا الأمر بالتفصيل جزاكم الله منا خيراً، وخاصة أن المسلمين في شك من هذا الأمر وفي اختلاف، وفقكم الله؟","title":"حكم الصلاة في أوقات الكراهة لسبب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن النبي الكريم عليه الصلاة والسلام أنه قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وثبت عنه عليه الصلاة والسلام أيضاً أنه نهى عن الصلاة بعد الصبح حتى ترتفع الشمس، وعن الصلاة بعد العصر حتى تغيب الشمس، فلهذا اختلف أهل العلم في هذه المسألة، هل يصلي تحية المسجد في العصر والصبح أم لا؟\nوالصواب: أنه يصليهما وأنهما غير داخلتان في النهي، فالركعتان اللتان يأتي بهما داخل المسجد غير داخلتين في النهي، هذا هو الصواب وهذا هو الأرجح؛ لأن أحاديث النهي عامة مخصوصة فقد استثني منها صلاة الجماعة لمن فاتته الجماعة فإنه يصلي مع الناس الجماعة، من صلى الجماعة في مسجد آخر أو في بيته ظناً أن الجماعة قد فاتته ثم جاء فإنه يصلي مع الناس العصر والفجر ولو كان قد صلى، وهذا مستثنى بالنص.\nكذلك صلاة الطواف في وقت العصر وفي وقت الصبح، الصحيح أنها لا بأس بها؛ لقول النبي ﷺ: لا تمنعوا أحداً طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار فصلاة التحية مثل ذلك -تحية المسجد- مثل هذا، فإذا دخل المسجد بعد صلاة العصر أو قبيل الغروب فالأفضل أنه يصلي ركعتين ثم يجلس، ومن جلس فلا حرج عليه، من جلس ولم يصل فلا حرج عليه لقوة الخلاف، ولكن لا ينبغي الإنكار من بعضهم على بعض، بل ينبغي في هذا التساهل والتسامح، فمن صلاهما إذا دخل قبل الغروب فهو أفضل، لكونها من ذوات الأسباب، ومن لم يصل ركعتين وجلس فلا حرج عليه، وهكذا الطواف من طاف بعد العصر، أو بعد صلاة الفجر، فصلى فهو أفضل، ومن أخر ركعتي الطواف حتى ارتفعت الشمس أو حتى غابت الشمس فلا حرج.\nوهكذا صلاة الكسوف لو كسفت الشمس بعد العصر أو طلعت كاسفة فالصواب أنه يشرع لها الصلاة، يشرع أن يصلي صلاة الكسوف في هذه الحالة، هذا هو الصواب وهذا هو الأرجح، ومن ترك ذلك فلا حرج عليه لقوة الخلاف في هذه المسألة.\nوبهذا يعلم المؤمن أن الأمر فيه سعة بحمد الله، وأنه لا ينبغي في مثل هذا التشديد والتنازع فالأمر في هذا واسع والحمد لله، من صلاهما -يعني: الركعتين ركعتي تحية المسجد- قبل غروب الشمس أو إذا دخل بعد صلاة الفجر فلا حرج عليه في ذلك وهو أفضل؛ لأنها من ذوات الأسباب؛ ولأنه في هذه الحال لا يقصد مشابهة المشركين، ومن جلس آخذاً بالنهي ولم يصل ركعتين فلا حرج عليه إن شاء الله والأمر في هذا واسع كما تقدم.\nالمقدم: بعض الناس يقول: إنه في وقت موسع ووقت مضيق في تحية المسجد مثلاً؟\nالشيخ: لا شك إن الوقت الموسع هو الذي بعد الصلاة قبل أن تصفر الشمس، فإذا اصفرت جاء الوقت المضيق، والصواب أنه لا حرج في صلاة التحية مطلقاً في المضيق والموسع، وهكذا صلاة الطواف، وهكذا صلاة الكسوف، هذا هو الصواب، ومن جلس ولم يصل ركعتين تحية المسجد فلا حرج كما تقدم لقوة الخلاف؛ ولأنه لا ينبغي بين أهل العلم وبين أهل الإيمان التنازع في مثل هذه الأمور؛ لأن كلاً من الطائفتين معه حجة ومعه دليل. نعم.","link":"https://binbaz.org.sa/fatwas/5520/حكم-الصلاة-في-اوقات-الكراهة-لسبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07101.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":8426,"question":"وحكم من أتى بركعتين بعد صلاة الفجر؟","title":"حكم صلاة ركعتين بعد صلاة الفجر","answer":"الجواب: فيه تفصيل: إن كان أتى بهما لأنهما سنة الفجر فلا بأس وهذا مشروع، أما أن يتطوع بركعتين بعد الفجر لا، غير مشروع، منهي عن ذلك. نعم.\nالمقدم: بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/6310/حكم-صلاة-ركعتين-بعد-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11903.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":8730,"question":"أختنا تسأل سؤالاً آخر وتقول: ما هي الأوقات المستحبة لصلاة التطوع، وهل تجوز الصلاة قبل المغرب بساعة صلاة تطوع؟","title":"ما الأوقات المستحبة لصلاة التطوع؟","answer":"الجواب: كل الليل والنهار محل تطوع كل الليل والنهار، الله جل وعلا جعل الليل والنهار خلفة لمن أراد أن يذكر أو أراد شكوراً سبحانه وتعالى، كما قال  في كتابه العظيم: وَهُوَ الَّذِي جَعَلَ اللَّيْلَ وَالنَّهَارَ خِلْفَةً لِمَنْ أَرَادَ أَنْ يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا [الفرقان:62].\nلكن يستثنى من ذلك أوقات النهي: ما بين صلاة الفجر إلى ارتفاع الشمس هذا وقت نهي عن الصلاة.\nكذلك ما بين صلاة العصر إلى غروب الشمس محل نهي عن الصلاة.\nكذلك عند قيامها قرب الظهر عند وقفة الشمس يعني عند توسطها كبد السماء وهي مدة قليلة، هذا وقت نهي أيضاً.\nأما بقية الأوقات مثل الضحى بعد ارتفاع الشمس إلى وقوف الشمس، بعد الظهر كل ما بين الظهر والعصر كله محل صلاة، الليل كله محل صلاة، فصلاة الضحى متأكدة وسنة مؤكدة، هكذا التهجد بالليل وبين العشاءين كله محل عبادة، فيه خير كثير وفضل كبير، لكن أوقات النهي لا يصلى فيها إلا لسبب كصلاة الطواف لمن طاف بعد العصر أو بعد الصبح يصلي صلاة الطواف، مثل سنة الوضوء لمن توضأ يصلي ركعتين سنة الوضوء ولو بعد العصر والصبح مثل لو كسفت الشمس بعد العصر شرع أن يصلى لها صلاة الكسوف في أصح قولي العلماء، مثل تحية المسجد لو دخل مسجد لأجل الدرس بعد العصر أو ليجلس فيه إلى الغروب سن له أن يصلي تحية المسجد، هذا مستثنى ويقال لها: ذوات الأسباب، هذا الصحيح أنها تستثنى ولا بأس بها في أوقات النهي على الصحيح من أقوال العلماء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6883/ما-الاوقات-المستحبة-لصلاة-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13503.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":9268,"question":"هل يجوز للمصلي أن يصلي بعد صلاة العصر تنفلاً؟","title":"حكم الصلاة بعد العصر نافلة","answer":"الجواب: ليس له ذلك، بعد العصر وقت نهي، وهكذا بعد الفجر، إلا إذا كان تحية المسجد دخل المسجد بعد العصر أو دخل المسجد بعد الفجر يريد الجلوس فيه للقراءة ولغير ذلك يصلي تحية المسجد ركعتين ثم يجلس ما لها وقت ليس لها وقت نهي، وهكذا الطواف لو طاف بعد العصر صلى ركعتي الطواف أو طاف بعد الصبح صلى ركعتي الطواف ليس لها وقت نهي. نعم.","link":"https://binbaz.org.sa/fatwas/7431/حكم-الصلاة-بعد-العصر-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15406.mp3","categories":["أوقات النهي"]},{"id":9889,"question":"هذا السائل من جمهورية الصومال محمود يقول: هل يجوز للمسلم أن يصلي نافلة في بعض الأوقات المنهي عنها مثل تحية المسجد قبل صلاة المغرب بقليل؟","title":"حكم الصلاة في الأوقات المنهي عنها","answer":"الجواب: يجوز له إذا كانت الصلاة ذات أسباب كدخوله المسجد قبل المغرب يصلي تحية المسجد لا بأس، لأن ذوات الأسباب الصحيح أنه ليس لها وقت نهي، ومثل صلاة الكسوف لو كسفت الشمس بعد العصر، شرع للناس صلاة الكسوف ومثل الطواف لو طاف بعد العصر في مكة، لو طاف بالكعبة بعد العصر، شرع له أن يصلي ركعتي الطواف ولو بعد العصر، أما غير ذوات الأسباب فلا يجوز إذا كان جالس في المسجد بعد صلاة العصر أو في بيته لا يصلي بعد العصر؛ لأنه وقت نهي أو بعد صلاة الفجر وقت نهي، لكن إذا كان أتى المسجد بعد العصر ليصلي المغرب جئت مبكراً يصلي تحية المسجد أو دخل المسجد بعد الفجر لأجل الدرس أو لأجل الراحة في المسجد أو لأسباب أخرى يصلي تحية المسجد. نعم.","link":"https://binbaz.org.sa/fatwas/8057/حكم-الصلاة-في-الاوقات-المنهي-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27301.mp3","categories":["أوقات النهي"]},{"id":10473,"question":"سؤاله الثاني يقول: هل هناك سنة بعد صلاة العصر، وهل تجوز الصلاة قبل الغروب؟","title":"حكم الصلاة بعد العصر وقبل الغروب","answer":"الجواب: ليس هناك سنة بعد العصر، بعد العصر نهي، وقت نهي، الرسول صلى الله عليه وسلم نهى عن الصلاة بعد العصر حتى تغيب الشمس، إلا من عليه فوائت هذا يقضيها ولو بعد العصر، لعموم قوله ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك فلو تذكر بعد العصر أن عليه الظهر ناسيها صلاها أو عليه الفجر ناسيها صلاها، أو غير ذلك، وهكذا لو أن إنسان دخل المسجد أو طاف بعد العصر في مكة صلى تحية المسجد وصلى ركعتي الطواف، وهكذا لو كسفت الشمس بعد العصر؛ لأن هذه من ذوات الأسباب، صلى بعد العصر، أما سنة راتبة بعد العصر لا، إلا خاصة بالنبي ﷺ كان يصلي بعد العصر، صلى بعد العصر ركعتين بسبب أنه شغل عنها بعد الظهر، ثم أثبتها، وسئل عنها: هل نقضيهما إذا فاتا؟ قال: لا. وأخبرت عائشة أنه أثبتها كان يصليها بعد العصر، فهذا شيء خاص به عليه الصلاة والسلام. نعم.\nالمقدم: وقبل الغروب ليس هناك؟\nالشيخ: ليس فيه شيء نعم، إلا مثلما تقدم، الشيء الذي يعرض من ذوات الأسباب كالكسوف والطواف بمكة .. دخول المسجد. نعم.","link":"https://binbaz.org.sa/fatwas/8639/حكم-الصلاة-بعد-العصر-وقبل-الغروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32005.mp3","categories":["أوقات النهي"]},{"id":10892,"question":"لها سؤال ثاني السائلة الأخت (ح. ع) من البحرين تقول: هل يجوز لي أن أصلي في وقت النهي عندما أبادر للوضوء لقراءة القرآن، أو للدعاء خصوصًا في أيام الجمعة، وذلك بعد العصر، علمًا بأنني لا أتوضأ عمدًا بنية الصلاة، إنما أتوضأ للدعاء كما ذكرت؟ جزاكم الله خيرًا.","title":"حكم أداء سنة الوضوء في أوقات النهي","answer":"الجواب:  إذا توضأ الإنسان في وقت النهي يصلي سنة الوضوء، ليس لها وقت نهي، إذا توضأ بعد الفجر، أو بعد العصر يشرع له أن يصلي ركعتين سنة الوضوء، سواء كان رجلًا أو امرأة. وهكذا لو دخل المسجد بعد العصر، أو بعد الفجر شرع له أن يصلي تحية المسجد، وليس لها وقت نهي، وهكذا لو كسفت الشمس بعد العصر شرع للمسلمين أن يصلوا صلاة الكسوف بعد العصر، وليس لها وقت نهي؛ لأن هذه كلها من ذوات الأسباب، والصلاة التي لها أسباب تفعل في وقت النهي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9069/حكم-اداء-سنة-الوضوء-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28606.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11090,"question":"السائل من الرياض أبو أحمد (أ. أ) يقول: لي والدة كبيرة في السن، وصاحبة طاعة -والحمد لله- تصلي الفروض في أوقاتها، وتحمد الله على ذلك، لكنها تتنفل طول الوقت، فما هي أوقات النهي التي لا يجوز لها أن تتنفل فيها، وحبذا لو عرفنا ذلك بالساعات؟","title":"أوقات النهي التي لا يجوز التنفل فيها","answer":"الجواب:  أوقات النافلة، كل الليل والنهار أوقات نافلة ما عدا أوقات النهي، وأوقات النهي من طلوع الفجر إلى ارتفاع الشمس، وعند وقوفها في كبد السماء قبل أن تميل إلى الأرض هذا يقال له: وقت الوقوف، ليس فيه صلاة، وبعد صلاة العصر إلى غروبها هذه أوقات النهي، إلا من ذوات الأسباب، إذا كان لها أسباب مثل: صلاة الكسوف بعد العصر تصلى، تحية المسجد، لو طاف بعد العصر يصلي .... صلاة الطواف في مكة، هذه يقال لها: ذوات الأسباب لا حرج على الصحيح. المقصود جميع الليل والنهار محل صلاة إلا وقتين: أحدهما: من طلوع الفجر إلى ارتفاع الشمس، هذا وقت نهي، لا يصلى فيه إلا صلاة الفجر وسنتها أو تحية المسجد، والوقت والآخر الطويل: ما بعد صلاة العصر إلى غروب الشمس. وهناك وقت ثالث قصير وهو: عند وقوفها، وهو وقت قصير عند وقوفها في كبد السماء حتى تزول، حتى تميل إلى الغرب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9268/اوقات-النهي-التي-لا-يجوز-التنفل-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28916.mp3","categories":["أوقات النهي"]},{"id":11167,"question":"تقول يا سماحة الشيخ: سمعت في برنامجكم نور على الدرب بأن الصلاة قبل المغرب مكروهة، بينوا لنا المقصود بذلك، هل هي صلاة التطوع، أم كركعتي الوضوء، جزاكم الله خيرًا؟","title":"حكم الصلاة بعد الفجر والعصر","answer":"الجواب:  الصلاة بعد العصر منهي عنها، وهكذا بعد طلوع الفجر سوى الفريضة وسنة الفجر إلى أن ترتفع الشمس، وهكذا بعد صلاة العصر إلى أن تغيب الشمس، هذان الوقتان وقتا نهي عن الصلاة، نهى النبي ﷺ عن الصلاة فيهما، لكن إذا كانت الصلاة من ذوات الأسباب فلا بأس بها، كصلاة الكسوف لو كسفت الشمس بعد العصر، وكتحية المسجد لمن دخل المسجد بعد العصر يريد أن يجلس فيه إلى غروب الشمس، أو يسمع حلقات العلم أو ما أشبه ذلك، يصلي تحية المسجد على الراجح على الصحيح. وهكذا سنة الوضوء إذا توضأ الإنسان يستحب له أن يصلي ركعتين ولو بعد العصر أو بعد الصبح، سنة الوضوء، أما النوافل التي ليس لها أسباب فهي منهي عنها، لا يجوز فعلها لا بعد الفجر ولا بعد العصر، حتى ترتفع الشمس في أول النهار، وحتى تغيب الشمس في آخر النهار، أما الفريضة فيصليها بكل حال، الفجر يصليها بكل حال، والعصر يصليها بكل حال، لو نام عن صلاة الفجر ولم يستيقظ إلا عند طلوع الشمس صلاها، وهكذا لو نام عن العصر فلم يستيقظ إلا بعد العصر بعد أن اصفرت الشمس، أو شغل عنها ونسيها ثم ذكر، صلاها في أي حال، ليس لها وقت نهي؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك. لكن لا يجوز للمسلم أن يؤخر الصلاة عن وقتها عمدًا، لا الفجر ولا غيرها، بل يجب عليه أن يصلي في الوقت، الفجر في وقتها، والظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها. هذا واجب على المسلمين أن يؤدوا هذه الصلوات الخمس في أوقاتها، لكن لو شغل الإنسان عن ذلك حتى نسي، صلاها متى يذكر، أو نام غلبه النوم فلم يستيقظ إلا عند طلوع الشمس، أو بعد طلوع الشمس صلاها، وهكذا في العصر، إذا استيقظ بعد أن تصفر الشمس صلاها أيضًا؛ لقوله ﷺ: «من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك»، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9341/حكم-الصلاة-بعد-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37108.mp3","categories":["أوقات النهي"]},{"id":11314,"question":"يقول: استنادًا لحديث بلال : ما توضأت إلا وصليت ركعتين بعد الوضوء، فأنا أتوضأ أحيانًا في أوقات نهي، مثال ذلك بعد صلاة العصر، أو بعد صلاة الفجر، أو عند غروب الشمس وعند طلوعها مثلًا، فهل عليَّ إثم إذا ما صليت ركعتي الوضوء؟ جزاكم الله خيرًا.","title":"حكم ركعتي الوضوء وصلاتها في أوقات النهي","answer":"الجواب:  المستحب الوضوء، المستحب الصلاة إذا توضأ الإنسان يصلي ركعتين سنة الوضوء في أي وقت ولو في وقت النهي؛ لأن الرسول ﷺ قال: من توضأ مثل وضوئي هذا ثم صلى ركعتين لا يحدث فيهما نفسه غفر له ما تقدم من ذنبه. فالمقصود أنه ﷺ كان إذا توضأ صلى ركعتين ورغب الناس في ذلك -عليه الصلاة والسلام- ويقال لها: سنة الوضوء، فلا مانع أن تصلى في وقت النهي وغيره لأنها سنة مؤكدة، نعم.","link":"https://binbaz.org.sa/fatwas/9505/حكم-ركعتي-الوضوء-وصلاتها-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37716.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11740,"question":"تقول في سؤالها الأخير: من الأوقات المنهي عنها الصلاة بعد العصر، فأنا كان علي نذر، ثم إني صليت نذرًا، وقرأت جزئين من القرآن الكريم، وصليت بعد العصر، فقالت لي أختي: إن ذلك من الأوقات المنهي عنها، فقلت لها: إن ذلك نذر، وليس قضاء صلاة مفروضة، فهل يجب علي الإعادة، أو أن ما فعلته كان صحيحًا؟ جزاكم الله خيرًا.","title":"حكم من نذر أن يصلي في وقت نهي","answer":"الجواب:  الواجب عليك الإعادة؛ لأنه ما هو محل صلاة، بعد العصر وبعد الفجر ليس محل صلاة إلا ذوات الأسباب، الصلاة المشروعة فيه كالكسوف بعد العصر، تحية المسجد، صلاة الطواف، أما النذر فله أوقات أخرى في إمكانك أن تصلي في الليل الظهر والضحى، وإن كنت عينت الصلاة بعد العصر قلت: أصلي بعد العصر هذا نذر معصية عليك كفارة يمين عن هذه الصلاة؛ لأن نذر الصلاة بعد العصر وبعد الصبح نذر معصية؛ لأنه ليس وقت الصلاة، وقت نهي؛ فعليك كفارة اليمين، كفارة النذر كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9922/حكم-من-نذر-ان-يصلي-في-وقت-نهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42114.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11997,"question":"متى تكون صلاة النافلة؟ وهل لها زمن محدد؟","title":"ما أوقات وقت صلاة النافلة؟","answer":"الجواب:  كل الليل والنهار صلاة نافلة، كل الليل والنهار صلاة نافلة، إلا بعد العصر حتى تغيب الشمس، وبعد الفجر حتى ترتفع الشمس، وعند قيامها عند الزوال، قبل الزوال بقليل حتى تزول، أوقات ثلاثة: بعد طلوع الفجر إلى ارتفاع الشمس، هذا واحد، عند قيامها وسط النهار؛ حتى تميل إلى الغروب إلى جهة الغرب، وهو زمن قصير وقوفها، الثالث: بعد صلاة العصر إلى غروبها، والباقي كله صلاة، الليل كله صلاة والنهار كله صلاة، ما عدا هذه الأوقات الثلاثة. المقدم: ما شاء الله.","link":"https://binbaz.org.sa/fatwas/10182/ما-اوقات-وقت-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43111.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11998,"question":"إذا عرض للمرء عارض، وأراد أن يصلي، وصادف وقت نهي، كأن يدخل مسجدًا، أو أن يطوف بالبيت؟","title":"حكم صلاة ذوات الأسباب في أوقات النهي","answer":"الجواب: إن كان ذوات الأسباب؛ لا بأس. المقدم: ذوات الأسباب. الشيخ: إذا كان مثل صلاة الطواف، إذا طاف بعد صلاة العصر، أو تحية المسجد، إذا دخل المسجد قبل المغرب، يصلي تحية المسجد ركعتين، نعم، أو صلاة الكسوف، كسفت الشمس بعد العصر؛ لأنها من ذوات الأسباب، يصلون صلاة الكسوف بعد العصر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10183/حكم-صلاة-ذوات-الاسباب-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43112.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":12456,"question":"تسأل أختنا عن الأوقات التي تحرم فيها الصلاة؟","title":"ما الأوقات التي تحرم الصلاة فيها؟","answer":"الجواب:  تحرم الصلاة في أوقات النهي صلاة النافلة، التي ليس لها أسباب بعد طلوع الفجر إلى ارتفاع الشمس، إلا سنة الفجر، وفريضة الفجر يصليها، تحية المسجد؛ لأن لها أسبابًا، وهكذا بعد صلاة العصر إلى غروب الشمس، وهكذا عند وقوف الشمس قبيل الظهر إذا وقفت، إذا صارت في كبد السماء حتى تزول، هذه أوقات النهي ثلاثة بالاختصار، وخمسة بالبسط، خمسة: أولها: طلوع الفجر إلى طلوع الشمس. الثاني: بعد طلوعها إلى أن ترتفع. والثالث: عند قيامها وسط السماء حتى تزول، وهو وقت قصير. والرابع: بعد صلاة العصر إلى أن تصفر الشمس. والخامس: إذا اصفرت حتى تغيب، كل هذه أوقات نهي، لا يصلى فيها تطوعًا، إلا إذا كان له سبب مثل: صلاة الكسوف، تحية المسجد، صلاة الطواف؛ فلا بأس على الصحيح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10669/ما-الاوقات-التي-تحرم-الصلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40410.mp3","categories":["أوقات النهي"]},{"id":13235,"question":"سماحة الشيخ! توقعات الحسابين وإخبارهم عن أوقات الكسوف والخسوف، هل يعمل به، وما حكم ذلك؟","title":"حكم العمل بأقوال الفلكيين في الكسوف والخسوف","answer":"الجواب:  أخبار الحسابين والفلكيين عن كسوف الشمس والقمر، وأن القمر يكسف في كذا، والشمس يكسف في كذا، قد يصدقون، وقد يخطئون، مثلما قال شيخ الإسلام ابن تيمية، وابن القيم وغيرهما، قد يخطئون وقد يصيبون، لكن لا يعمل بأقوالهم إلا إذا شاهدنا الكسوف بأعيننا؛ لأن الرسول ﷺ قال: إن الشمس والقمر آيتان من آيات الله، لا يكسفان لموت أحد، ولا لحياته، ولكن الله يرسلها يخوف بها عباده، فإذا رأيتم ذلك؛ فصلوا، وادعوا حتى ينكشف ما بكم وفي اللفظ الآخر: فإذا رأيتم ذلك؛ فافزعوا إلى ذكر الله ودعائه واستغفاره. فنحن مأمورون أن نفزع إلى الصلاة، والذكر والدعاء عند المشاهدة، عندما نشاهد الكسوف والخسوف، أما إخبار الفلكيين والحسابين أنها تكسف الشمس في يوم كذا، أو صباح كذا، أو القمر في ليلة كذا، فهذا لا يعمل به إلا إذا رؤي، إذا وجد، فإن الناس يصلون، ويعملون بما شرع الله، جل وعلا.  وهكذا لو قيل: كسفت في أمريكا، أو في انجلترا، أو في مصر ما نعمل به، لكن يعمل به الذي كسفت عنده، إذا شاهدوه في مصر؛ شرع لهم أن يصلوا هناك، وإذا شاهدوا الكسوف في لندن؛ شرع لهم الصلاة هناك، وإذا وجد الكسوف عندهم في أمريكا؛ شرع لهم الصلاة، وهكذا، أما البلد التي ما فيها كسوف، ولكن يبلغهم الخبر أنه وقع في أمريكا، أو في كذا؛ لا يشرع لهم. وهكذا قول الحسابين أن القمر يكسف في ليلة أربعة عشر في ساعة كذا، أو في ليلة خمسة عشر ساعة كذا، أو الشمس تكسف في يوم ثمانية وعشرين، أو في تسعة وعشرين، أو في ثلاثين؛ كل هذا لا يعمل به، ولا ينبغي أن يعمل به، ولا يجوز؛ لأن الرسول ﷺ علق الحكم بالمشاهدة قال: إذا رأيتم ذلك، فينبغي التنبه لهذا، ونسأل الله لأولئك الحسابين الهداية، نسأل الله لنا ولهم الهداية، فاشتغلوا بأشياء لا تعنيهم، ولا تهمهم، ولا تترتب عليها مصالح، اللهم المستعان. المقدم: اللهم المستعان، جزاكم الله خيرًا سماحة الشيخ على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/11517/حكم-العمل-باقوال-الفلكيين-في-الكسوف-والخسوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51303.mp3","categories":["صلاة الخسوف","أوقات النهي"]},{"id":13688,"question":"بعد ذلك ننتقل إلى رسالة وصلت من السائل (ي. أ. م) يقول: سماحة الشيخ! ما هي الأوقات التي نهي عنها في الصلاة؟ جزاكم الله خيرًا.","title":"ما الأوقات التي نهي عن الصلاة فيها؟","answer":"الجواب: الأوقات خمسة التي نهي فيها عن الصلاة: بعد صلاة العصر إلى أن تصفر الشمس، وبعد اصفرارها إلى أن تغيب، هذه وقتان. والثالث: عند وقوفها وسط النهار حتى تميل إلى المغرب وهو وقت قصير. والرابع: بعد طلوع الفجر إلى طلوع الشمس. والخامس: بعد طلوعها حتى ترتفع قيد رمح، هذه خمسة، ويجوز اختصارها إلى ثلاثة، فيقال: ثلاثة من طلوع الفجر إلى ارتفاع الشمس، ومن بعد صلاة العصر إلى غروب الشمس، هذان اثنان، والثالث: عند وقوفها قبيل الظهر حتى تزول، وهو وقت قليل عند توسطها السماء قبل أن تميل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12040/ما-الاوقات-التي-نهي-عن-الصلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51917.mp3","categories":["أوقات النهي"]},{"id":13944,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من الرياض وباعثتها إحدى الأخوات من هناك ورمزت إلى اسمها بالحروف (هـ. م. أ) أختنا تسأل وتقول: ما حكم من يصلي قبل الظهر بربع ساعة أو عشر دقائق، حيث أنني سمعت من إحدى الأخوات أن هذا الوقت من الأوقات المنهي عن الصلاة فيها؟ نرجو التوضيح جزاكم الله خيرًا.","title":"حكم الصلاة وقت وقوف الشمس","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا يجوز للمسلم أن يصلي قبل الظهر في وقت وقوف الشمس؛ لأنه من أوقات النهي، وقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال ثلاث ساعات لا يصلى فيهن ولا يقبر فيهن الموتى: بعد صلاة الصبح حتى تطلع الشمس، وحين تقف الشمس حتى تزول، وبعد صلاة العصر حتى تغيب الشمس.\nفالمقصود أنه قبيل الظهر لا يصلي وهذا الوقت ليس بالطويل بل هو وقت قصير عند توسط الشمس كبد السماء يسمى: وقوف الشمس، يسمى وقت الوقوف، فلا يجوز التعبد بالصلاة ذاك الوقت حتى تزول الشمس يعني: حتى يؤذن الظهر، إذا زالت الشمس صلى الإنسان ما شاء، أما قبل الزوال فالواجب التوقف عن التطوع بالصلاة، والوقت ليس بالطويل يقارب ربع ساعة أو ثلث ساعة، وإذا احتاط الإنسان وتوقف عن الصلاة قبل الأذان بنصف ساعة تقريبًا للاحتياط حسن، فإذا زالت الشمس انتهى وقت النهي إلى أن يصلي العصر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12348/حكم-الصلاة-وقت-وقوف-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60401.mp3","categories":["أوقات النهي"]},{"id":14142,"question":"في آخر أسئلته يقول هذا السائل: أسأل عن حكم التنفل في وقت النهي؟","title":"حكم التنفل وقت النهي","answer":"الجواب: التنفل لا يجوز وقت النهي إلا إذا كان له سبب، مثل صلاة الكسوف لو كسفت الشمس بعد العصر، أو صلاة تحية المسجد دخل المسجد بعد العصر ليجلس ينتظر المغرب يصلي تحية المسجد؛ لقوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين؛ ولقوله ﷺ: إن الشمس والقمر آيتان من آيات الله لا ينكسفان لموت أحد من الناس ولا لحياته، فإذا رأيتم ذلك فصلوا وادعوا هذا يعم أوقات النهي وغير أوقات النهي.\nوهكذا الطواف لو طاف بعد العصر يصلي ركعتين- ركعتي الطواف- أو بعد الفجر كذلك، لقوله ﷺ: يا بني عبد مناف! لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12583/حكم-التنفل-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54607.mp3","categories":["أوقات النهي"]},{"id":14550,"question":"السائل إبراهيم بن عبدالعزيز أبو حامد، يقول: الحقيقة له مجموع من الأسئلة، والأخ إبراهيم متواصل مع البرنامج، يقول في هذا سماحة الشيخ، في حالة خسوف القمر بعد صلاة الفجر وشوهد، هل تصلى صلاة الخسوف في هذا الوقت، أم لا؟، وكذلك بعد صلاة العصر؟وجهونا يا سماحة الشيخ.","title":"هل تصلى الخسوف والكسوف في أوقات النهي؟","answer":"الجواب: نعم، إذا خسفت الشمس بعد العصر شرعت الصلاة والذكر والدعاء والصدقة والتكبير؛ لأن الرسول ﷺ قال: إن الشمس والقمر آيتان من آيات الله، لا ينكسفان لموت أحد ولا لحياته، فإذا رأيتم ذلك فصلوا، وادعوا حتى يكشف ما بكم وفي الحديث الآخر يقول ﷺ: فإذا رأيتم ذلك فافزعوا إلى ذكر الله ودعائه واستغفاره. وثبت عنه ﷺ «أنه لما رأى الكسوف أمر بالصدقة والتكبير والعتق» هذا هو السنة، ولو بعد العصر على الصحيح، وقال بعض أهل العلم: إنه لا يصلى لها بعد العصر؛ لأنه وقت نهي.  والصواب: أنه يصلى لها؛ لأن صلاة الكسوف من ذوات الأسباب، وذوات الأسباب تفعل ولو في وقت النهي مثل صلاة الطواف إذا طاف بعد العصر، مثل تحية المسجد إذا دخل المسجد يريد يصلي المغرب دخل قبل المغرب يصلي ركعتي التحية، مثل الوضوء لو توضأ بعد العصر يصلي ركعتين، هذا هو الصواب، ذوات الأسباب لا بأس بها في وقت النهي، وصلاة الكسوف من ذوات الأسباب، هذا هو الصواب، والراجح من قولي العلماء. وهكذا إذا كسف القمر في آخر الليل، أو في أول النهار يصلى لكسوفه أفضل، ومن ترك فلا حرج؛ لأن وقته قد ذهب، قد ذهب سلطانه بعد الفجر، ولم يبق إلا الشيء اليسير من سلطانه، فمن صلى فهو أفضل، ويخفف حتى يصلي الفجر بعد ذلك في وقتها، ومن لم يصل فلا حرج؛ لأن القمر إذا طلع الفجر ذهب سلطانه، ولم يبق منه إلا اليسير، فمن صلى بعد طلوع الفجر له لعموم الأحاديث فلا بأس، وهو أفضل، ومن ترك ذلك فلا حرج، وإن صلى فليخفف يبدأ بصلاة الخسوف قبل الفجر، ثم يصلي صلاة الفجر في وقتها قبل الشمس.\nالمقدم: وكذلك بعد صلاة العصر يا سماحة الشيخ؟ الشيخ: تقدم بعد صلاة العصر خسوف الشمس، نعم، يصلي، تقدم، نعم.","link":"https://binbaz.org.sa/fatwas/13046/هل-تصلى-الخسوف-والكسوف-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55510.mp3","categories":["صلاة الخسوف","أوقات النهي"]},{"id":15857,"question":"هذا سائل يقول -يا سماحة الشيخ-: قال ﷺ: لا يجلس أحدكم حتى يصلي ركعتين أي: تحية المسجد، وفي حديث آخر: لا صلاة بعد صلاة الصبح وصلاة العصر فهل لي أن أعمل بهذين الحديثين في كل يوم أعمل بحديث، يوم أصلي وآخر ما أصلي؟","title":"حكم صلاة تحية المسجد لمن دخل بعد العصر؟","answer":"الجواب: السنة الصلاة، إذا دخل المسجد يصلي ركعتين، وتسمى هذه من ذوات الأسباب، والنهي عن لا يصلي بعد الصبح يعني: صلاة بغير سبب، أما إذا كان بسبب مثل الكسوف، كسفت الشمس بعد العصر يصلون صلاة الكسوف، وإذا دخل المسجد بعد العصر ليجلس في المسجد، أو ليحضر حلقة العلم، يصلي ركعتين؛ لقول النبي ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس هذا هو السنة، حتى ولو كان الإمام يخطب يوم الجمعة، إذا دخل المسجد يصلي ركعتين، والإمام يخطب لا بأس، هذا الواجب عليه هذا المشروع، يصلي ركعتين، ثم يجلس، وتسمى: تحية المسجد، ولو في وقت النهي، ولو في حال خطبة الإمام يوم الجمعة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14448/حكم-صلاة-تحية-المسجد-لمن-دخل-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57619.mp3","categories":["أوقات النهي"]},{"id":16159,"question":"هذا سائل مقيم في المملكة العربية السعودية، يقول -سماحة الشيخ-: صلاة تحية المسجد هل يصليها الإنسان كلما يدخل المسجد أي: بعد كل صلاة؟ أم مرة واحدة في اليوم؟ وهذه الصلاة، هل تكفي عن السنة، أم لا؟ جزاكم الله خيرًا.","title":"حكم تحية المسجد لكل دخول إلى المسجد","answer":"الجواب: السنة لمن دخل المسجد وهو على طهارة أن يصلي ركعتين تحية المسجد؛ لقول النبي ﷺ: إذا دخل أحد المسجد؛ فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس هذا السنة في أي وقت: في وقت الضحى، في الظهر، في العصر، في المغرب.. في أي وقت، ليس لها وقت نهي على الصحيح، حتى ولو بعد العصر إذا دخل لا يجلس، ينتظر المغرب، يصلي ركعتين، أو دخل بعد الفجر لحضور حلقات العلم، أو ليجلس في المسجد يصلي ركعتين إذا كان على طهارة قبل أن يجلس، ليس لها وقت نهي، هذا هو المشروع للمسلم، وهي سنة مؤكدة. ولو دخل إلى المسجد مرات؛ صلى كلما دخل، لو دخل الضحى مرتين، أو ثلاثًا، أو الظهر، أو العصر، أو الليل، كلما دخل وهو على طهارة؛ يصلي ركعتين، ولو دخل وصلى الراتبة راتبة الظهر سدت عن تحية المسجد، لو صلى راتبة الظهر ركعتين، أو أربع ركعات، الراتبة قبل الظهر السنة أربع تسليمتين، فإذا صلاهما؛ سدت عن تحية المسجد، وهكذا إذا دخل الفجر وهو ما صلى الراتبة في بيته، صلى الراتبة في المسجد؛ كفته عن تحية المسجد، ركعتين سنة الفجر تكفي عن تحية المسجد.. والحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14822/حكم-تحية-المسجد-لكل-دخول-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58004.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":17084,"question":"هل يجوز للمرء أن يصلي تحية المسجد، ولو كانت الشمس مستوية في كبد السماء؟","title":"ما حكم تحية المسجد والشمس في كبد السماء؟","answer":"الجواب: نعم، متى دخل المسجد يصلي، في وقت قيام الشمس، أو بعد العصر، أو بعد الصبح؛ لأن هذين الركعتين متعلقة بدخول المسجد، ومن أسبابها دخول المسجد، فإذا دخل المسجد صلى ركعتين قبل أن يجلس مطلقًا في أي وقت، هذا هو الصواب، وهكذا لو طاف بالكعبة في مكة صلى ركعتي الطواف، ولو بعد العصر، ولو بعد الصبح؛ لأنها من ذوات الأسباب؛ لقوله ﷺ يا بني عبد مناف! لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15911/ما-حكم-تحية-المسجد-والشمس-في-كبد-السماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83105.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":17105,"question":"السائل من مصر- محافظة الغربية أبو رية زكي، يقول: سماحة الشيخ! إذا دخلت المسجد قبل أذان المغرب بقليل، فهل يجب علي صلاة ركعتين تحية للمسجد، وسنة الوضوء؟ أم الصلاة مكروهة في هذا الوقت؟","title":"هل تُشرع صلاة تحية المسجد في أي وقت؟","answer":"الجواب: الصواب أنه يستحب أن يصلي تحية المسجد، ولو كان دخوله قبل الغروب؛ لأن هذا الوقت للنهي، للصلاة المجردة، أما ذات الأسباب مثل: تحية المسجد، وسنة الوضوء.. صلاة الكسوف، لا بأس به، يصلي تحية المسجد. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15898/هل-تشرع-صلاة-تحية-المسجد-في-اي-وقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58904.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":17534,"question":"السائل الذي رمز لاسمه بـ (أ. أ) من الأردن أرسل بمجموعة من الأسئلة منها هذا السؤال يقول: سماحة الشيخ! الأوقات المكروهة في الصلاة ثلاثة، وسؤالي: لماذا كرهت؟الشيخ: إيش؟المقدم: يقول: الأوقات المكروهة في الصلاة ثلاثة، وسؤالي: لماذا كرهت هذه الأوقات؟","title":"أسباب كراهية الصلاة في أوقات الكراهة","answer":"الجواب: لأنها يسجد لها الكفار عند غروب الشمس، وعند طلوعها، وعند وقوفها، فالرسول ﷺ نهى عن ذلك لئلا يتشبه المسلم بالكفار، لكن إذا كان لها سبب كصلاة تحية المسجد إذا دخل بعد العصر أو بعد صلاة الفجر فإن الصواب أنه يصليها، هذا هو الصحيح من أقوال العلماء إذا كانت الصلاة لها سبب مثل تحية المسجد .. ومثل صلاة الكسوف، لو كسفت الشمس بعد العصر فالسنة أن يصلي صلاة الكسوف، هذا هو الصواب، وهكذا لو طاف بعد العصر في مكة طاف بالكعبة بعد الفجر أو بعد العصر فإنه يصلي ركعتي الطواف؛ لأنها من ذوات الأسباب لقوله ﷺ: يا بني عبد مناف لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار، ولقوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، ولقوله ﷺ في الشمس والقمر: إنهما آيتان من آيات الله لا ينكسفان لموت أحد ولا لحياته، فإذا رأيتم ذلك فافزعوا إلى الصلاة، وفي اللفظ الآخر: فصلوا وادعوا، فهذا يعم أوقات النهي وغيرها، هذا هو الصواب: أن ذوات الأسباب تفعل في وقت النهي، أما غيرها من التطوع لا فلا يفعل. نعم.\nالمقدم: أحسن الله إليكم وأثابكم الله يا شيخ.","link":"https://binbaz.org.sa/fatwas/16466/اسباب-كراهية-الصلاة-في-اوقات-الكراهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77514.mp3","categories":["أوقات النهي"]},{"id":18364,"question":"يقول السائل في فقرته الأخيرة: هل تحية المسجد مشروعة في جميع الأوقات، وفي أوقات النهي يا سماحة الشيخ؟","title":"حكم تحية المسجد في جميع الأوقات","answer":"الجواب: نعم، تحية المسجد مشروعة في جميع الأوقات؛ لأنها من ذوات الأسباب، فإذا دخل المسجد بعد العصر ليجلس حتى ينتظر المغرب، أو للدروس، أو لأسباب أخرى يصلي تحية المسجد، هكذا لو جاء بعد الفجر يصلي تحية المسجد؛ لأنها من ذوات الأسباب، النبي ﷺ يقول: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس. وهكذا لو كسفت الشمس بعد العصر صلي لها، نعم؛ لأنها من ذوات الأسباب، وهكذا لو طاف في مكة، طاف بالكعبة بعد العصر أو بعد الفجر فإنه يصلي ركعتين لقوله ﷺ: يا بني عبد مناف! لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. نعم المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17434/حكم-تحية-المسجد-في-جميع-الاوقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78325.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":19312,"question":"نعود في بداية هذه الحلقة إلى رسالة إحدى الأخوات المستمعات، تقول المستمعة هدى أختنا أرسلت بما يقرب من ثلاثين سؤالًا عرضنا جزءًا من أسئلتها في حلقة مضت ونرجو أن نتمكن من عرض البعض أيضًا في هذه الحلقة، تسأل سماحة الشيخ وتقول: ما هو الوقت الذي تمنع صلاة النافلة فيه ؟","title":"أوقات النهي عن صلاة النافلة","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد أوضح النبي ﷺ الأوقات التي تمنع فيها الصلاة وهي خمسة على سبيل الإيضاح:\nالأول: ما بعد طلوع الفجر إلى طلوع الشمس، هذا وقت نهي لا يفعل فيه إلا صلاة الفجر وسنة الفجر ركعتان قبلها، فإن فاتت قبلها صلاها بعدها، هذا هو الوقت الأول. والوقت الثاني: من طلوع الشمس إلى ارتفاعها قيد رمح، وهذا وقت مضيق لا تجوز فيه الصلاة؛ لأنه وقت نهي وحينئذٍ يسجد الكفار للشمس عباد الشمس يسجدون لها عند طلوعها. والوقت الثالث: عند قيام الشمس؛ يعني: عند وقوفها قبل الزوال في وسط النهار وهو وقت قصير فإن الشمس سائرة، ولكن عند توسطها في السماء يسمى وقوف، وهذا الوقت وقت قصير لا يصلى فيه حتى تميل إلى جهة الغرب. والرابع: بعد صلاة العصر إلى أن تصفر الشمس. والخامس: بعد اصفرارها إلى أن تغيب، فهذه خمسة أوقات لا يصلى فيها لكن يستثنى من ذلك على الصحيح ذوات الأسباب من الصلوات فإنها تصلى في هذه الأوقات وهي: صلاة الطواف لو طاف بعد العصر أو طاف بعد الصبح أو طاف بعد أذان الفجر فإنه يصلي سنة الطواف لقول النبي ﷺ: يا بني عبد مناف ! لا تمنعوا أحداً طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار هذا مستثنى من أوقات النهي. ومن ذلك أيضًا: تحية المسجد لو دخل الإنسان المسجد يريد أن يجلس فيه إلى الغروب أو دخله بعد الصبح ليجلس فيه إلى طلوع الشمس فإن السنة أن يصلي ركعتين تحية المسجد لقوله عليه الصلاة والسلام في الحديث الصحيح: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين ولأنه ﷺ لما رأى رجلاً دخل المسجد وهو يخطب الناس يوم الجمعة عليه الصلاة والسلام أمره أن يقوم فيصلي ركعتين، فلولا أنها متأكدة لما أمره بهذه الحال بأن يقوم ويصلي ركعتين وقال: إذا جاء أحدكم والإمام يخطب فليصل ركعتين وليتجوز فيهما. ومنها: صلاة الكسوف، لو كسفت الشمس بعد العصر أو عند طلوع الشمس شرعت صلاة الكسوف لقوله ﷺ: إن الشمس والقمر آيتان من آيات الله لا ينخسفان لموت أحد من الناس ولا لحياته، فإذا رأيتم ذلك فصلوا وادعوا وفي اللفظ الآخر: فافزعوا إلى الصلاة فهذا يعم أوقات النهي وغيرها، ومنها: سنة الوضوء إذا توضأ فإنه يشرع له أن يصلي ركعتين لصحة الأحاديث عن النبي في ذلك عليه الصلاة والسلام، ومنها قوله ﷺ: إذا تطهر أحدكم فأحسن الطهور ثم صلى ركعتين لا يحدث فيهما نفسه غفر له ما تقدم من ذنبه متفق على صحته. فهذه الصلوات التي لها أسباب لا مانع من فعلها في أوقات النهي، وهي مستثناة ومخصوصة من أدلة النهي، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا. سماحة الشيخ! ماذا عن قضاء الفوائت فيما إذا نسي إنسان صلاة؟ الشيخ: كذلك مستثناة قضاء الفوائت لو مثلًا نام عن الظهر والعصر فإنه يصليهما في وقت العصر ولو بعد اصفرار الشمس، وكذلك لو تذكر صلاة عليه بعد العصر صلاها بعد العصر، أو تذكرها بعد الصبح صلاها بعد الصبح، لقوله ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك، فهذه مستثناة أيضًا من النهي. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18495/اوقات-النهي-عن-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89401.mp3","categories":["أوقات النهي"]},{"id":19393,"question":"من الجماهيرية الليبية رسالة بعث بها المستمع مفتاح محمد التونسي، يسأل عددًا من الأسئلة، في أحدها يقول: في صلاة المغرب عندما يأتي المصلي لصلاة المغرب ويدخل المسجد، هل عليه أن يصلي تحية المسجد أم لا؟ وهل يصليها بعد الانتهاء من صلاة المغرب؟","title":"حكم صلاة تحية المسجد في وقت النهي","answer":"الجواب: السنة لمن دخل المسجد أن يصلي الركعتين تحية المسجد سواء المغرب وإلا غير المغرب حتى ولو في آخر النهار قبل الغروب يصلي تحية المسجد؛ لأنها من ذوات الأسباب، ليس لها وقت نهي يصلي ركعتين ثم يجلس، هذه يقال لها: تحية المسجد، إذا دخل المسجد قبل الصلاة قبل الغروب قبل إقامة الصلاة؛ يصلي هاتين الركعتين. أما سنة المغرب الراتبة فهي بعدها ركعتان بعد المغرب، وهكذا العشاء ركعتان بعد العشاء، لكن تحية المسجد هي للمسجد، ليس لها تعلق بصلاة المغرب، إذا دخل المسجد في أي وقت وهو على وضوء صلى ركعتين عصرًا أو ظهرًا أو ليلًا أو نهارًا. وهكذا صلاة الكسوف إذا كسفت الشمس ظهرًا أو ضحىً أو عصرًا يصلي صلاة الكسوف، لأنها من ذوات الأسباب، هكذا لو طاف بعد العصر أو بعد الفجر؛ يصلي ركعتي الطواف؛ لأنها من ذوات الأسباب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18614/حكم-صلاة-تحية-المسجد-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74008.mp3","categories":["أوقات النهي"]}]
